            a[i+3] = b[i+2] + c[i+3] * d[i+3];
            a[i+4] = b[i+3] + c[i+4] * d[i+4];
            a[i+5] = b[i+4] + c[i+5] * d[i+5];
            a[i+6] = b[i+5] + c[i+6] * d[i+6];
            a[i+7] = b[i+6] + c[i+7] * d[i+7];
        }
        // Scalar tail
